export default async function install(app) {
 const searchMount=app.getMount('station-search'), resultMount=app.getMount('coverage-results');
 const layer=app.layers[app.config.layerId]; app.assert(layer,'Police stations are unavailable.'); await layer.load();
 const [serviceArea,networkService,ServiceAreaParameters,FeatureSet,Graphic,Portal]=await Promise.all([app.import('esri/rest/serviceArea'),app.import('esri/rest/networkService'),app.import('esri/rest/support/ServiceAreaParameters'),app.import('esri/rest/support/FeatureSet'),app.import('esri/Graphic'),app.import('esri/portal/Portal')]);
 const {nameField,addressField,detailFields,minutes,travelMode:desiredMode}=app.config, oidField=layer.objectIdField;
 const areas=await app.createResultLayer({id:app.config.resultLayerId,title:minutes+'-minute driving coverage',geometryType:'polygon',fields:[{name:'Station',type:'string'},{name:'Minutes',type:'double'},{name:'Mode',type:'string'}],renderer:{type:'simple',symbol:{type:'simple-fill',color:[24,117,170,0.2],outline:{color:'#1875aa',width:2}}},popupTemplate:{title:'{Station}',content:'Driving coverage: {Minutes} minutes ({Mode})'}});
 app.map.reorder(areas.layer,0);
 const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
 const style=make('style');style.textContent='.nycp-ui{display:flex;flex-direction:column;gap:8px;min-width:0;font:13px/1.4 system-ui;color:var(--calcite-color-text-1)}.nycp-ui input{box-sizing:border-box;width:100%;min-width:0;padding:9px;border:1px solid var(--calcite-color-border-2);background:var(--calcite-color-foreground-1);color:inherit}.nycp-list{display:flex;flex-direction:column;gap:5px;max-height:300px;overflow:auto}.nycp-item{display:flex;flex-direction:column;gap:3px;text-align:left;padding:9px;border:1px solid var(--calcite-color-border-2);border-radius:4px;background:var(--calcite-color-foreground-1);color:inherit;cursor:pointer}.nycp-item:hover{border-color:var(--calcite-color-brand)}.nycp-meta{font-size:12px;color:var(--calcite-color-text-2)}.nycp-title{font-weight:600}.nycp-error{color:var(--calcite-color-status-danger)}';
 const ui=make('div',undefined,'nycp-ui'),input=make('input'),count=make('div','Loading stations…','nycp-meta'),list=make('div',undefined,'nycp-list');input.type='search';input.placeholder='Station, address or borough';input.setAttribute('aria-label','Search police stations');
 ui.append(input,count,list);searchMount.replaceChildren(style,ui);resultMount.setAttribute('aria-live','polite');
 const message=(title,body,error=false)=>{const box=make('div',undefined,'nycp-ui');box.append(make('div',title,'nycp-title'),make('div',body,error?'nycp-error':'nycp-meta'));resultMount.replaceChildren(box);};
 message('Select a station','Choose from the list or click a map marker.');
 let generation=0,disposed=false,highlight,serviceUrl,mode,modePromise;let stations=[];
 const getMode=()=>{if(!modePromise)modePromise=(async()=>{const portal=new Portal(app.portalUrl?{url:app.portalUrl}:{});await portal.load();serviceUrl=portal.helperServices?.serviceArea?.url;app.assert(serviceUrl,'No service-area helper service is configured for this portal.');const d=await networkService.fetchServiceDescription(serviceUrl);const modes=d.supportedTravelModes??[];mode=modes.find(m=>String(m.name).toLowerCase()===desiredMode.toLowerCase())||modes.find(m=>m.type==='automobile'&&m.impedanceAttributeName===m.timeAttributeName);app.assert(mode,'No time-based driving mode is available.');return mode;})().catch(e=>{modePromise=null;throw e;});return modePromise;};
 const solve=async(graphic)=>{const current=++generation,oid=graphic?.getObjectId?.()??graphic?.attributes?.[oidField];message('Calculating coverage…','Reading station location.');if(highlight){highlight.remove();highlight=null;}await areas.clear();
 try{app.assert(oid!=null,'The selected station has no object ID.');const q=layer.createQuery();q.objectIds=[oid];q.outFields=['*'];q.returnGeometry=true;const r=await layer.queryFeatures(q);if(disposed||current!==generation)return {ok:false,reason:'superseded'};const station=r.features[0];app.assert(station?.geometry,'The selected station has no usable location.');const stationName=String(station.attributes[nameField]??'Police station');message(stationName,'Calculating '+minutes+'-minute driving coverage…');const chosen=await getMode();if(disposed||current!==generation)return {ok:false,reason:'superseded'};
 const solved=await serviceArea.solve(serviceUrl,new ServiceAreaParameters({facilities:new FeatureSet({features:[new Graphic({geometry:station.geometry,attributes:station.attributes})]}),travelMode:chosen,defaultBreaks:[minutes],travelDirection:'from-facility',outSpatialReference:app.view.spatialReference,trimOuterPolygon:true,returnFacilities:false}));
 if(disposed||current!==generation)return {ok:false,reason:'superseded'};const polygons=solved.serviceAreaPolygons?.features??[];if(!polygons.length){message(stationName,'No reachable service-area polygon was returned.');return {ok:false,stationName,objectId:oid,polygonCount:0,travelMode:chosen.name};}
 await areas.replaceFeatures(polygons.map(p=>({geometry:p.geometry,attributes:{Station:stationName,Minutes:minutes,Mode:chosen.name}})));if(disposed||current!==generation)return {ok:false,reason:'superseded'};
 try{const lv=await app.view.whenLayerView(layer);if(current===generation&&!disposed)highlight=lv.highlight([oid]);}catch(ignore){}
 if(current===generation&&!disposed){await app.view.goTo(polygons.map(p=>p.geometry),{duration:600}).catch(()=>{});if(current===generation&&!disposed)message(stationName,[station.attributes[addressField],station.attributes.BORO,minutes+' minutes · '+chosen.name+' · Away from station'].filter(Boolean).join(' | '));}
 return {ok:true,stationName,objectId:oid,polygonCount:polygons.length,travelMode:chosen.name,minutes,travelDirection:'from-facility'};
 }catch(e){if(!disposed&&current===generation){message('Coverage unavailable',e.message||String(e),true);app.reportError(e);}return {ok:false,reason:e.message||String(e)};}};
 app.actions.register('select-station',async({graphic})=>solve(graphic));
 const render=()=>{const term=input.value.trim().toLowerCase();const rows=stations.filter(s=>s.search.includes(term));count.textContent=rows.length+' of '+stations.length+' stations';list.replaceChildren();if(!rows.length)list.append(make('div','No matching stations.','nycp-meta'));for(const s of rows){const b=make('button',undefined,'nycp-item');b.type='button';b.dataset.oid=String(s.oid);b.append(make('span',s.name,'nycp-title'),make('span',s.details,'nycp-meta'));list.append(b);}};
 const click=async(e)=>{const button=e.target.closest('button[data-oid]');if(!button||!list.contains(button))return;const s=stations.find(s=>String(s.oid)===button.dataset.oid);if(s)await app.actions.invoke('select-station',{graphic:new Graphic({attributes:{[oidField]:s.oid}})});};
 list.addEventListener('click',click);input.addEventListener('input',render);
 app.onCleanup(()=>{disposed=true;++generation;list.removeEventListener('click',click);input.removeEventListener('input',render);if(highlight)highlight.remove();areas.clear();searchMount.replaceChildren();resultMount.replaceChildren();});
 try{const q=layer.createQuery();q.where='1=1';q.outFields=[oidField,nameField,addressField,...detailFields];q.returnGeometry=false;q.orderByFields=[nameField];const r=await layer.queryFeatures(q);app.assert(!r.exceededTransferLimit,'Station search was truncated by the service.');if(disposed)return;stations=r.features.map(f=>{const a=f.attributes,name=String(a[nameField]??'Police station'),details=[a[addressField],...detailFields.map(k=>a[k])].filter(Boolean).join(' · ');return {oid:a[oidField],name,details,search:(name+' '+details).toLowerCase()};});render();}catch(e){count.textContent='Station search unavailable: '+(e.message||String(e));}
}